// Processed real photos (generated by `node scripts/build-images.mjs` from assets-source/).
// photos.json lists every slot that has a valid photo; a slot without one is simply missing here and the
// caller keeps its SVG placeholder: `photoOr('hero-home', placeholders.heroWide)`.
import manifest from './photos.json'
import './photos.css'

const urls = import.meta.glob('./*.webp', { eager: true, query: '?url', import: 'default' })
const url = (slot, width) => urls[`./${slot}-${width}.webp`]

export const photos = Object.fromEntries(
  Object.entries(manifest).map(([slot, m]) => {
    const fallbackWidth = [...m.widths].reverse().find((w) => w <= 1200) ?? m.widths[0]
    return [
      slot,
      {
        src: url(slot, fallbackWidth),
        srcSet: m.widths.map((w) => `${url(slot, w)} ${w}w`).join(', '),
        sizes: m.sizes,
        width: m.w,
        height: m.h,
        bg: `phc-${slot}`,
        alt: m.alt || '',
      },
    ]
  }),
)

export const photoOr = (slot, fallback) => photos[slot] ?? fallback
